<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WastedToken Mint — Physical Tokens for Digital Legends</title>
<style>
  :root {
    color-scheme: dark;
    --ink: #f5efe1;
    --muted: #aaa391;
    --black: #070807;
    --panel: #10110f;
    --acid: #d8ff45;
    --bronze: #d18a48;
    --silver: #d9e0e3;
    --gold: #f0c95a;
    --line: rgba(255,255,255,.12);
  }

  * { box-sizing: border-box; }

  html {
    scroll-behavior: smooth;
    background: var(--black);
  }

  body {
    margin: 0;
    color: var(--ink);
    background:
      radial-gradient(circle at 50% -10%, rgba(216,255,69,.08), transparent 28rem),
      linear-gradient(180deg, #0b0c0a 0%, #060706 100%);
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    overflow-x: hidden;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    opacity: .18;
    background-image:
      repeating-linear-gradient(90deg, transparent 0 79px, rgba(255,255,255,.025) 80px),
      repeating-linear-gradient(0deg, transparent 0 79px, rgba(255,255,255,.018) 80px);
    mask-image: linear-gradient(to bottom, black, transparent 80%);
  }

  a { color: inherit; text-decoration: none; }

  .shell {
    width: min(1240px, calc(100% - 40px));
    margin-inline: auto;
  }

  header {
    height: 82px;
    display: flex;
    align-items: center;
    border-bottom: 1px solid var(--line);
    position: relative;
    z-index: 5;
