  header .shell {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .brand {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: .18em;
    text-transform: uppercase;
  }

  .brand-mark {
    width: 34px;
    aspect-ratio: 1;
    border: 2px solid var(--acid);
    border-radius: 50%;
    display: grid;
    place-items: center;
    color: var(--acid);
    box-shadow: inset 0 0 0 4px #090a08, inset 0 0 0 5px rgba(216,255,69,.45);
    font-size: 13px;
    letter-spacing: 0;
