  nav {
    display: flex;
    gap: 30px;
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: .13em;
    text-transform: uppercase;
  }

  nav a:hover { color: var(--acid); }

  .hero {
    min-height: 790px;
    display: grid;
    grid-template-columns: .8fr 1.2fr;
    align-items: center;
    gap: 10px;
    padding: 46px 0 70px;
