  h1 span {
    display: block;
    color: transparent;
    -webkit-text-stroke: 1px rgba(245,239,225,.65);
  }

  .hero-copy {
    max-width: 490px;
    color: var(--muted);
    font-size: 17px;
    line-height: 1.7;
