<script>
(() => {
  "use strict";

  const hero = document.getElementById("coin-hero");
  const hctx = hero.getContext("2d", { alpha: false });

  const MATERIALS = {
    bronze: {
      dark: "#3a1c0c", edge: "#74401d", base: "#a95f2d",
      mid: "#d6914f", light: "#ffe0a0", ink: "#3a1a09", glow: "#ffc26b"
    },
    silver: {
      dark: "#343b3e", edge: "#687277", base: "#aeb8bb",
      mid: "#d5dcde", light: "#ffffff", ink: "#30373a", glow: "#eaffff"
    },
    gold: {
      dark: "#4a3005", edge: "#8a650e", base: "#c79420",
      mid: "#efcb55", light: "#fff3a0", ink: "#503405", glow: "#fff1a1"
    },
    black: {
      dark: "#030305", edge: "#17141e", base: "#24232a",
      mid: "#4d485d", light: "#c6baff", ink: "#020204", glow: "#9c88ff"
    }
  };

  function clamp(v, a, b) {
    return Math.max(a, Math.min(b, v));
  }

  function pointOnRim(cx, cy, scale, halfT, u, v, n, angle, side) {
    const ca = Math.cos(angle), sa = Math.sin(angle);
    return {
      x: cx + scale * (u.x * ca + v.x * sa) + side * halfT * n.x,
      y: cy + scale * (u.y * ca + v.y * sa) + side * halfT * n.y
    };
  }

  function line(ctx, x1, y1, x2, y2) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  function faceGradient(ctx, radius, mat, shinePosition) {
    const g = ctx.createLinearGradient(-radius, -radius * .15, radius, radius * .15);
    const p = clamp(.5 + shinePosition * .25, .25, .75);
    const stops = [
      [0, mat.dark],
      [clamp(p - .22, .01, .98), mat.base],
      [clamp(p - .075, .02, .98), mat.mid],
      [p, mat.light],
      [clamp(p + .045, .02, .98), mat.glow],
      [clamp(p + .15, .02, .99), mat.base],
      [1, mat.dark]
    ].sort((a,b) => a[0] - b[0]);

    let last = -1;
    for (const [raw, color] of stops) {
      const pos = Math.max(raw, last + .0001);
      if (pos <= 1) {
        g.addColorStop(pos, color);
        last = pos;
      }
    }
    return g;
  }

  function drawRaisedText(ctx, text, x, y, size, mat, dx, dy, weight = 900) {
    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;

    ctx.fillStyle = "rgba(0,0,0,.5)";
    ctx.fillText(text, x + dx * 2.3, y + dy * 2.3);

    ctx.fillStyle = mat.light;
    ctx.globalAlpha = .55;
    ctx.fillText(text, x - dx, y - dy);

    ctx.globalAlpha = 1;
    ctx.fillStyle = mat.mid;
    ctx.fillText(text, x, y);

    ctx.strokeStyle = mat.ink;
    ctx.globalAlpha = .72;
    ctx.lineWidth = Math.max(1.2, size * .035);
    ctx.strokeText(text, x, y);
    ctx.restore();
  }

  function drawFront(ctx, radius, mat, shine, angle) {
    const dx = Math.cos(angle) * radius * .012;
    const dy = Math.sin(angle * .73) * radius * .01;

    ctx.fillStyle = faceGradient(ctx, radius, mat, shine);
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fill();

    const vignette = ctx.createRadialGradient(-radius*.18, -radius*.22, radius*.08, 0, 0, radius);
    vignette.addColorStop(0, "rgba(255,255,255,.13)");
    vignette.addColorStop(.65, "rgba(255,255,255,0)");
    vignette.addColorStop(1, "rgba(0,0,0,.46)");
    ctx.fillStyle = vignette;
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.lineWidth = radius * .035;
    ctx.strokeStyle = mat.light;
    ctx.globalAlpha = .58;
    ctx.beginPath(); ctx.arc(0, 0, radius * .89, 0, Math.PI * 2); ctx.stroke();

    ctx.strokeStyle = mat.ink;
    ctx.globalAlpha = .82;
    ctx.lineWidth = radius * .018;
    ctx.beginPath(); ctx.arc(0, 0, radius * .78, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, radius * .52, 0, Math.PI * 2); ctx.stroke();

    ctx.globalAlpha = 1;
    drawRaisedText(ctx, "WASTEDTOKEN", 0, -radius * .66, radius * .105, mat, dx, dy, 900);
    drawRaisedText(ctx, "MINT • EST. 2025", 0, radius * .66, radius * .075, mat, dx, dy, 800);

    for (let i = 0; i < 16; i++) {
      const a = Math.PI * 2 * i / 16;
      const x = Math.cos(a) * radius * .585;
      const y = Math.sin(a) * radius * .585;
      ctx.fillStyle = "rgba(0,0,0,.38)";
      ctx.beginPath();
      ctx.arc(x + dx * 1.8, y + dy * 1.8, radius * .018, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = mat.light;
      ctx.globalAlpha = .7;
      ctx.beginPath();
      ctx.arc(x - dx, y - dy, radius * .015, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.globalAlpha = 1;
    ctx.save();
    ctx.translate(dx * 2.2, dy * 2.2);
    ctx.fillStyle = "rgba(0,0,0,.52)";
    drawW(ctx, radius);
    ctx.restore();

    ctx.save();
    ctx.translate(-dx, -dy);
    ctx.fillStyle = mat.light;
    ctx.globalAlpha = .72;
    drawW(ctx, radius);
    ctx.restore();

    ctx.fillStyle = mat.mid;
    ctx.globalAlpha = 1;
    drawW(ctx, radius);
    ctx.strokeStyle = mat.ink;
    ctx.lineWidth = radius * .018;
    ctx.stroke();

    ctx.fillStyle = mat.ink;
    ctx.globalAlpha = .7;
    ctx.beginPath();
    ctx.arc(0, radius * .29, radius * .038, 0, Math.PI * 2);
    ctx.fill();

    ctx.globalAlpha = 1;
  }

  function drawW(ctx, radius) {
    ctx.beginPath();
    ctx.moveTo(-radius*.37, -radius*.31);
    ctx.lineTo(-radius*.23, radius*.31);
    ctx.lineTo(-radius*.05, radius*.02);
    ctx.lineTo(radius*.08, radius*.31);
    ctx.lineTo(radius*.39, -radius*.31);
    ctx.lineTo(radius*.20, -radius*.31);
    ctx.lineTo(radius*.07, radius*.02);
    ctx.lineTo(-radius*.07, -radius*.27);
    ctx.lineTo(-radius*.22, radius*.02);
    ctx.lineTo(-radius*.19, -radius*.31);
    ctx.closePath();
    ctx.fill();
  }

  function drawBack(ctx, radius, mat, shine, angle) {
    const dx = Math.cos(angle) * radius * .012;
    const dy = Math.sin(angle * .81) * radius * .01;

    ctx.fillStyle = faceGradient(ctx, radius, mat, -shine);
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fill();

    const shade = ctx.createRadialGradient(radius*.2, -radius*.3, 0, 0, 0, radius);
    shade.addColorStop(0, "rgba(255,255,255,.18)");
    shade.addColorStop(.7, "rgba(255,255,255,0)");
    shade.addColorStop(1, "rgba(0,0,0,.5)");
    ctx.fillStyle = shade;
    ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

    ctx.strokeStyle = mat.light;
    ctx.globalAlpha = .52;
    ctx.lineWidth = radius * .034;
    ctx.beginPath(); ctx.arc(0, 0, radius*.89, 0, Math.PI*2); ctx.stroke();

    ctx.strokeStyle = mat.ink;
    ctx.globalAlpha = .8;
    ctx.lineWidth = radius * .018;
    ctx.beginPath(); ctx.arc(0, 0, radius*.79, 0, Math.PI*2); ctx.stroke();

    ctx.globalAlpha = .55;
    ctx.lineWidth = radius * .012;
    for (let i = 0; i < 8; i++) {
      const a = Math.PI * 2 * i / 8;
      const x1 = Math.cos(a) * radius * .57;
      const y1 = Math.sin(a) * radius * .57;
      const x2 = Math.cos(a) * radius * .72;
      const y2 = Math.sin(a) * radius * .72;
      ctx.strokeStyle = mat.ink;
      line(ctx, x1, y1, x2, y2);
      ctx.fillStyle = mat.light;
      ctx.beginPath(); ctx.arc(x2, y2, radius*.025, 0, Math.PI*2); ctx.fill();
    }

    ctx.globalAlpha = 1;
    drawRaisedText(ctx, "10,000", 0, -radius*.09, radius*.27, mat, dx, dy, 900);
    drawRaisedText(ctx, "TOKENS", 0, radius*.19, radius*.115, mat, dx, dy, 900);
    drawRaisedText(ctx, "PROOF OF TIME WASTED", 0, -radius*.62, radius*.07, mat, dx, dy, 800);
    drawRaisedText(ctx, "SERIES 0001 • PHYSICAL ISSUE", 0, radius*.62, radius*.055, mat, dx, dy, 800);

    ctx.globalAlpha = 1;
  }

  function renderCoin(ctx, width, height, t, materialName, options = {}) {
    const mat = MATERIALS[materialName] || MATERIALS.bronze;
    const cx = width * .5;
    const cy = height * (options.cy || .5);
    const scale = Math.min(width, height) * (options.scale || .355);
    const halfT = scale * (options.thickness || .115);

    const yaw = Math.PI * 2 * t;
    const flip = Math.PI * 4 * t;

    const u = { x: Math.cos(yaw), y: 0, z: -Math.sin(yaw) };
    const v = {
      x: Math.sin(yaw) * Math.sin(flip),
      y: Math.cos(flip),
      z: Math.cos(yaw) * Math.sin(flip)
    };
    const n = {
      x: Math.sin(yaw) * Math.cos(flip),
      y: -Math.sin(flip),
      z: Math.cos(yaw) * Math.cos(flip)
    };

    ctx.setTransform(1,0,0,1,0,0);
    const bg = ctx.createRadialGradient(cx, cy, 10, cx, cy, Math.max(width,height)*.66);
    bg.addColorStop(0, options.card ? "#141512" : "#151713");
    bg.addColorStop(.55, options.card ? "#0d0e0c" : "#0b0d0a");
    bg.addColorStop(1, options.card ? "#080907" : "#050604");
    ctx.fillStyle = bg;
    ctx.fillRect(0,0,width,height);

    const shadow = ctx.createRadialGradient(cx, cy + scale*.54, 2, cx, cy + scale*.54, scale*.95);
    shadow.addColorStop(0, "rgba(0,0,0,.58)");
    shadow.addColorStop(1, "rgba(0,0,0,0)");
    ctx.save();
    ctx.scale(1, .28);
    ctx.fillStyle = shadow;
    ctx.beginPath();
    ctx.ellipse(cx, (cy + scale*.62)/.28, scale*.86, scale*.33, 0, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();

    const segments = 112;
    for (let i = 0; i < segments; i++) {
      const a1 = Math.PI * 2 * i / segments;
      const a2 = Math.PI * 2 * (i + 1) / segments;
      const am = (a1+a2)*.5;
      const radialZ = u.z * Math.cos(am) + v.z * Math.sin(am);
      if (radialZ < -.03) continue;

      const p1 = pointOnRim(cx,cy,scale,halfT,u,v,n,a1,1);
      const p2 = pointOnRim(cx,cy,scale,halfT,u,v,n,a2,1);
      const p3 = pointOnRim(cx,cy,scale,halfT,u,v,n,a2,-1);
      const p4 = pointOnRim(cx,cy,scale,halfT,u,v,n,a1,-1);

      const light = clamp(.28 + .62 * (
        Math.cos(am)*u.x*.65 + Math.sin(am)*v.x*.65 +
        Math.cos(am)*u.y*-.35 + Math.sin(am)*v.y*-.35
      ), 0, 1);

      ctx.fillStyle = i % 2
        ? (light > .55 ? mat.mid : mat.edge)
        : (light > .55 ? mat.light : mat.dark);

      ctx.beginPath();
      ctx.moveTo(p1.x,p1.y); ctx.lineTo(p2.x,p2.y);
      ctx.lineTo(p3.x,p3.y); ctx.lineTo(p4.x,p4.y);
      ctx.closePath();
      ctx.fill();

      if (i % 2 === 0) {
        ctx.strokeStyle = "rgba(0,0,0,.52)";
        ctx.lineWidth = Math.max(1, scale*.006);
        line(ctx, p1.x,p1.y,p4.x,p4.y);
      }
    }

    const frontVisible = n.z >= 0;
    const side = frontVisible ? 1 : -1;
    const faceCx = cx + side * halfT * n.x;
    const faceCy = cy + side * halfT * n.y;

    ctx.save();
    if (frontVisible) {
      ctx.setTransform(
        scale*u.x, scale*u.y,
        scale*v.x, scale*v.y,
        faceCx, faceCy
      );
    } else {
      ctx.setTransform(
        -scale*u.x, -scale*u.y,
        scale*v.x, scale*v.y,
        faceCx, faceCy
      );
    }

    ctx.beginPath();
    ctx.arc(0,0,1,0,Math.PI*2);
    ctx.clip();

    const shine = Math.sin(yaw * 1.15 + flip * .18);
    if (frontVisible) drawFront(ctx, 1, mat, shine, yaw + flip);
    else drawBack(ctx, 1, mat, shine, yaw - flip);

    ctx.restore();

    ctx.save();
    ctx.setTransform(
      frontVisible ? scale*u.x : -scale*u.x,
      frontVisible ? scale*u.y : -scale*u.y,
      scale*v.x, scale*v.y,
      faceCx, faceCy
    );
    ctx.strokeStyle = mat.light;
    ctx.globalAlpha = .75;
    ctx.lineWidth = .018;
    ctx.beginPath(); ctx.arc(0,0,.965,0,Math.PI*2); ctx.stroke();
    ctx.strokeStyle = mat.dark;
    ctx.globalAlpha = .88;
    ctx.lineWidth = .022;
    ctx.beginPath(); ctx.arc(0,0,.995,0,Math.PI*2); ctx.stroke();
    ctx.restore();

    ctx.setTransform(1,0,0,1,0,0);
  }

  function renderHero(t) {
    renderCoin(hctx, hero.width, hero.height, t, "bronze", {
      scale: .365,
      thickness: .12,
      cy: .495
    });
  }

  const editionTimes = {
    bronze: .045,
    silver: .965,
    gold: .075,
    black: .935
  };

  document.querySelectorAll(".edition").forEach(tile => {
    const canvas = tile.querySelector(".edition-canvas");
    const ctx = canvas.getContext("2d", { alpha: false });
    const name = tile.dataset.edition;
    renderCoin(ctx, canvas.width, canvas.height, editionTimes[name], name, {
      scale: .37,
      thickness: .105,
      cy: .5,
      card: true
    });
  });

  document.querySelectorAll("button.buy").forEach(button => {
    button.addEventListener("click", () => {
      const old = button.textContent;
      button.textContent = "Added ✓";
      button.style.background = "#f5efe1";
      setTimeout(() => {
        button.textContent = old;
        button.style.background = "";
      }, 1400);
    });
  });

  let running = true;
  let raf = 0;
  const start = performance.now();
  const duration = 9200;

  function animate(now) {
    if (!running) return;
    const t = ((now - start) % duration) / duration;
    renderHero(t);
    raf = requestAnimationFrame(animate);
  }

  renderHero(0);
  raf = requestAnimationFrame(animate);

  window.demo = {
    canvas: hero,
    setTime(t) {
      const exact = clamp(Number.isFinite(Number(t)) ? Number(t) : 0, 0, 1);
      renderHero(exact);
    },
    pause() {
      running = false;
      if (raf) cancelAnimationFrame(raf);
    }
  };
})();
</script>
